	val contentRating: String? = null,
	val runtimeMinutes: UInt? = null,
	val poster: Image? = null,
	val backdrop: Image? = null,
	val logo: Logo? = null,
	/// The page's colours, from the backdrop.
	val accent: AccentPalette? = null,
	val quality: Quality? = null,
	val hdr: Boolean,
	val inList: Boolean,
	/// Absent for a series without a playable episode.
	val play: PlayAction? = null,
	/// A series that allows playing a random episode.
	val shuffle: Boolean,
	/// Only seasons and episodes that have something to play.
	val seasons: List<SeasonView>
)

@Serializable
data class TitleView (
	val slug: String,
	val status: LoadStatus,
	val detail: TitleDetailView? = null,
	val problem: Problem? = null
)

/// A track by id; no id turns subtitles off.
@Serializable
data class TrackChoice (
	val id: String? = null
)

@Serializable
data class UploadRequest (
	/// The request without a body; the shell sends the form as its body.
	val request: HttpRequest,
	/// The handle the shell gave the core for the picked file.
	val file: String,
	/// The form part the file goes in, with the file's own name (servers type images by its
	/// extension).
	val field: String
)

@Serializable
data class UserCode (
	val code: String
)

@Serializable
data class WatchlistChange (
	val titleId: String,
	/// True to add the title to My List, false to remove it.
	val listed: Boolean
)

@Serializable
sealed class PlayerCommand {
	/// Replace what is playing. Sent again for a quality or audio-file switch, starting where
	/// playback was.
	@Serializable
	@SerialName("load")
	data class Load(val content: PlayerLoad): PlayerCommand()
	@Serializable
	@SerialName("play")
	data object Play: PlayerCommand()
	@Serializable
	@SerialName("pause")
	data object Pause: PlayerCommand()
	@Serializable
	@SerialName("seek")
	data class Seek(val content: PlayerSeek): PlayerCommand()
	/// Switch to the stream's embedded audio rendition in this language.
	@Serializable
	@SerialName("selectAudio")
	data class SelectAudio(val content: AudioRendition): PlayerCommand()
	/// Show this subtitle track, or none.
	@Serializable
	@SerialName("selectSubtitles")
	data class SelectSubtitles(val content: SubtitleSelection): PlayerCommand()
	/// Stop and release the player.
	@Serializable
	@SerialName("stop")
	data object Stop: PlayerCommand()
}

@Serializable
sealed class SocketCommand {
	@Serializable
	@SerialName("open")
	data class Open(val content: SocketOpen): SocketCommand()
	@Serializable
	@SerialName("send")
	data class Send(val content: SocketSend): SocketCommand()
	@Serializable
	@SerialName("close")
	data class Close(val content: EffectRef): SocketCommand()
}

